import glob, email

for f in sorted(glob.glob('Correspondence/**/*.eml', recursive=True)):
    print('='*50)
    print(f)
    with open(f, 'rb') as fp:
        msg = email.message_from_binary_file(fp)
        for h in ['From', 'To', 'Cc', 'Subject', 'Date']:
            print(f'{h}: {msg.get(h)}')
        print('-'*20)
