import docx

def read_docx(path):
    doc = docx.Document(path)
    text = []
    for p in doc.paragraphs:
        if p.text.strip():
            text.append(p.text)
    for table in doc.tables:
        for row in table.rows:
            text.append(' | '.join(cell.text.strip() for cell in row.cells))
    return '\n'.join(text)

print('=== DSR_Ph3_Weekly_Meeting_Notes.docx ===')
print(read_docx('Meeting Notes/DSR_Ph3_Weekly_Meeting_Notes.docx'))
print('=== DSR_Ph3_PreApp_Meeting_Notes.docx ===')
print(read_docx('Meeting Notes/DSR_Ph3_PreApp_Meeting_Notes.docx'))
