import glob, os, re

files = glob.glob('**/*', recursive=True)
for f in files:
    if os.path.isfile(f) and not f.endswith('.pdf') and not f.endswith('.py'):
        try:
            with open(f, 'r', errors='ignore') as fp:
                content = fp.read()
                matches = re.findall(r'[A-Z][a-z]+ [A-Z][a-z]+.*(?:Principal|Sundial|President|Director|PE|P\.E\.)', content)
                if matches:
                    print(f, matches[:5])
        except:
            pass
